+    @Test void PP1c_invalidUtf8NamesCannotCollapseIntoOneObjectKey() throws Exception {
+        Process fixture = new ProcessBuilder("/bin/sh", "-c",
+                "printf first > \"$(printf '\\200')\"; printf second > \"$(printf '\\201')\"")
+                .directory(root.toFile()).start();
+        assertTrue(fixture.waitFor(5, java.util.concurrent.TimeUnit.SECONDS));
+        assertEquals(0, fixture.exitValue());
+        Map<Path, String> before = new HashMap<>();
+        try (var entries = Files.newDirectoryStream(root)) {
+            for (Path entry : entries) before.put(entry, Files.readString(entry));
+        }
+        assertEquals(2, before.size());
+        assertEquals(1, before.keySet().stream().map(Path::toString).distinct().count());
+        Failure rejected = assertThrows(Failure.class, () -> {
+            List<FileRow> accepted = scanFiles(root, () -> {});
+            assertEquals(2, accepted.size(), "Red must reach accepted invalid inventory");
+            assertEquals(1, accepted.stream().map(FileRow::objectKey).distinct().count(),
+                    "Red must demonstrate two raw names collapsing to one key");
+        });
+        assertEquals("UNSAFE_MEDIA_PATH", rejected.code());
+        try (var entries = Files.newDirectoryStream(root)) {
+            Set<Path> after = new HashSet<>();
+            for (Path entry : entries) {
+                after.add(entry);
+                assertEquals(before.get(entry), Files.readString(entry));
+            }
+            assertEquals(before.keySet(), after);
+        }
+    }
